    "15+ years of building dreams with international quality, innovative prefab technology, and an unwavering commitment to excellence.": "আন্তর্জাতিক মান, উদ্ভাবনী প্রিকাস্ট প্রযুক্তি এবং শ্রেষ্ঠত্বের অবিচল প্রতিশ্রুতিতে ১৫+ বছর ধরে স্বপ্নের আবাসন তৈরি করছি।",
