    "*Interest rates are indicative of local Bangladesh banking norms (9-11%). Please consult with your bank for exact approval amounts.": "*সুদের হার বাংলাদেশের স্থানীয় ব্যাংকিং নিয়ম (৯-১১%) অনুযায়ী নির্দেশক। সুনির্দিষ্ট অনুমোদিত পরিমাণের জন্য আপনার ব্যাংকের সাথে পরামর্শ করুন।",
