    // Company Profile Paragraphs (Cholito Bangla)
    "BONGSHAI HOUSING is a premier Real Estate and Housing Company serving all over Bangladesh — anywhere, anyplace. While we have major hubs in Dhaka, Chattogram, Gazipur, Cumilla, and North Bengal, we undertake Engineering-Procurement-Construction & Commissioning (EPC&C) projects nationwide. We have the experience and resources to execute complex pre-engineered steel buildings (PEB) and prefab housing on time with international standards of quality, safety, and reliability.": "বংশাই হাউজিং হলো সারা বাংলাদেশে কাজ করা একটি শীর্ষস্থানীয় রিয়েল এস্টেট ও আবাসন নির্মাণকারী প্রতিষ্ঠান — যেকোনো জায়গায়, যেকোনো স্থানে সেবা দিতে আমরা প্রতিশ্রুতিবদ্ধ। ঢাকা, চট্টগ্রাম, গাজীপুর, কুমিল্লা এবং উত্তরবঙ্গে আমাদের প্রধান হাব রয়েছে। এছাড়া আমরা দেশজুড়ে সফলভাবে ইঞ্জিনিয়ারিং-প্রকিউরমেন্ট-কনস্ট্রাকশন অ্যান্ড কমিশন (ইপিসি অ্যান্ড সি) প্রকল্প বাস্তবায়ন করে থাকি। সর্বোচ্চ মান, সুরক্ষা ও বিশ্বস্ততার আন্তর্জাতিক মানদণ্ড বজায় রেখে সময়মতো জটিল পূর্ব-নির্মিত ইস্পাত ভবন (PEB) এবং প্রেফ্যাব আবাসন সম্পন্ন করার জন্য আমাদের রয়েছে প্রয়োজনীয় অভিজ্ঞতা ও সমৃদ্ধ সম্পদ।",
    "From affordable cottage projects in Bogra to luxury container resorts in Probachol — and every district in between — we gear up to excel stakeholders' expectations with our modern technology and sophisticated, experienced professional workforce, responsible for the entire process from design and materials supply to construction and test operation.": "বগুড়ার সাশ্রয়ী প্রেফ্যাব কটেজ প্রকল্প থেকে শুরু করে পূর্বাচলের বিলাসবহুল কনটেইনার রিসোর্ট — এবং দেশের প্রতিটি জেলাজুড়ে — আমরা আধুনিক প্রযুক্তি ও অভিজ্ঞ পেশাদার প্রকৌশলী দলের মাধ্যমে সবার প্রত্যাশা পূরণে প্রস্তুত। নকশা তৈরি ও কাঁচামাল সরবরাহ থেকে শুরু করে অবকাঠামো নির্মাণ ও পরীক্ষামূলক পরিচালনা পর্যন্ত সম্পূর্ণ কাজের দায়িত্ব আমরা নিষ্ঠার সাথে পালন করি।",

    "2.5\" Pre-cast RCC (Outer)": "২.৫\" প্রিকাস্ট আরসিসি (আউটার)",
    "2\" Pre-cast RCC (Inner)": "২\" প্রিকাস্ট আরসিসি (ইনার)",
    "While we make every effort to ensure the accuracy of the information on this website, it is provided on an \"as-is\" and \"as available\" basis. Bongshai Housing does not warrant that the website will run uninterrupted or error-free. Project specifics, pricing, and structural models are finalized exclusively via signed legal contracts and agreements; website details represent estimated representations for promotion only.": "এই ওয়েবসাইটে প্রদত্ত তথ্যের নিখুঁত সঠিকতা নিশ্চিত করতে আমরা সর্বোচ্চ চেষ্টা করি, তবে সকল তথ্য সাময়িক নমুনা হিসেবে প্রদত্ত। সাইটটি কোনো ত্রুটি বা বাধা ছাড়া চলবে — বংশাই হাউজিং এমন নিশ্চয়তা প্রদান করে না। যেকোনো প্রজেক্টের নির্দিষ্ট বিবরণী, মূল্য ও অবকাঠামোগত মডেল কেবলমাত্র স্বাক্ষরিত আইনি চুক্তির মাধ্যমেই চূড়ান্ত হয়; ওয়েবসাইটের বিবরণসমূহ কেবল প্রচারণামূলক নমুনা।",

