    "Cumilla": "কুমিল্লা",
    "A modern two-story residential steel building successfully completed in Bodorgonj, Rangpur. As a leading prefab contractor in the Rangpur division, we delivered this durable steel frame construction for long-term reliability.": "রংপুরের বদরগঞ্জে সফলভাবে নির্মিত একটি আধুনিক দ্বি-তল আবাসিক প্রিকাস্ট স্টিল ভবন। রংপুর বিভাগের শীর্ষস্থানীয় প্রেফ্যাব কন্ট্রাক্টর হিসেবে দীর্ঘমেয়াদী নির্ভরযোগ্যতায় আমরা এই অবকাঠামো নির্মাণ করেছি।",
    "An elegant multi-story commercial showroom delivered in Chotrogram. Bongshai Housing provides top-tier pre-engineered building (PEB) solutions for businesses across the Chattogram district.": "চট্টগ্রামে সফলভাবে হস্তান্তরিত এক দৃষ্টিনন্দন বহুতল বাণিজ্যিক শোরুম। বংশাই হাউজিং চট্টগ্রাম জেলাজুড়ে ব্যবসায়িক প্রতিষ্ঠানের জন্য প্রিমিয়াম পূর্ব-নির্মিত ইস্পাত ভবন (PEB) সলিউশন প্রদান করে।",
    "A beautifully finished interior space in Cumilla. Our steel building expertise ensures sturdy construction and premium quality residential prefab housing across the Cumilla region.": "কুমিল্লায় অনবদ্যভাবে নির্মিত আবাসিক প্রেফ্যাব প্রকল্প। আমাদের আধুনিক প্রযুক্তি কুমিল্লা অঞ্চলে নিশ্চিত করে সর্বোচ্চ মানসম্পন্ন ও টেকসই আবাসন।",

    // Contact Page (From User Screenshots)
    "Contact Bongshai Housing": "বংশাই হাউজিংয়ের সাথে যোগাযোগ",
    "Ready to start your housing project? Reach out for a free consultation. Our team is ready to help Saturday to Thursday, 9 AM – 7 PM.": "আপনার আবাসন প্রকল্প শুরু করতে প্রস্তুত? বিনামূল্যে বিশেষজ্ঞ পরামর্শের জন্য আজই আমাদের সাথে যোগাযোগ করুন। শনি থেকে বৃহস্পতিবার (সকাল ৯টা - সন্ধ্যা ৭টা) আমাদের টিম আপনার সেবায় নিয়োজিত।",
