    "Have a question about our services or want to discuss your project? Reach us through any of the channels below.": "আমাদের সেবা বা আবাসন প্রকল্প সম্পর্কে কোনো প্রশ্ন আছে? নিচের যেকোনো মাধ্যমে আমাদের সাথে নির্দ্বিধায় যোগাযোগ করুন।",
