    "Compact and durable security huts designed for single-guard deployment at residential or commercial entrances. This product is built to international standards, ensuring longevity, safety, and comfort. We offer full customization for colors, dimensions, and interior fittings to suit your exact project requirements.": "আবাসিক বা বাণিজ্যিক প্রবেশদ্বারে একক-গার্ড স্থাপনের জন্য ডিজাইন করা কমপ্যাক্ট এবং টেকসই নিরাপত্তা কুঁড়েঘর। এই পণ্যটি আন্তর্জাতিক মানের জন্য নির্মিত, দীর্ঘায়ু, নিরাপত্তা এবং আরাম নিশ্চিত করে। আমরা আপনার সঠিক প্রকল্পের প্রয়োজনীয়তা অনুসারে রঙ, মাত্রা এবং অভ্যন্তরীণ জিনিসপত্রের জন্য সম্পূর্ণ কাস্টমাইজেশন অফার করি।",
    "Multi-purpose prefabricated booths that can be customized for toll collections, parking attendants, or check-points. This product is built to international standards, ensuring longevity, safety, and comfort. We offer full customization for colors, dimensions, and interior fittings to suit your exact project requirements.": "বহুমুখী প্রিফেব্রিকেটেড বুথ যা টোল সংগ্রহ, পার্কিং অ্যাটেনডেন্ট বা চেক-পয়েন্টের জন্য কাস্টমাইজ করা যেতে পারে। এই পণ্যটি আন্তর্জাতিক মানের জন্য নির্মিত, দীর্ঘায়ু, নিরাপত্তা এবং আরাম নিশ্চিত করে। আমরা আপনার সঠিক প্রকল্পের প্রয়োজনীয়তা অনুসারে রঙ, মাত্রা এবং অভ্যন্তরীণ জিনিসপত্রের জন্য সম্পূর্ণ কাস্টমাইজেশন অফার করি।",
