    ". While we have major hubs in Dhaka, Chattogram, Gazipur, Cumilla, and North Bengal, we undertake Engineering-Procurement-Construction & Commissioning (EPC&C) projects nationwide. We have the experience and resources to execute complex pre-engineered steel buildings (PEB) and prefab housing on time with international standards of quality, safety, and reliability.": ". যদিও ঢাকা, চট্টগ্রাম, গাজীপুর, কুমিল্লা এবং উত্তরবঙ্গে আমাদের প্রধান হাব রয়েছে, আমরা দেশব্যাপী ইঞ্জিনিয়ারিং-প্রকিউরমেন্ট-কনস্ট্রাকশন অ্যান্ড কমিশনিং (EPC&C) প্রকল্প হাতে নিই। আন্তর্জাতিক মানের গুণমান, নিরাপত্তা এবং নির্ভরযোগ্যতার সাথে জটিল প্রি-ইঞ্জিনিয়ার্ড স্টিল বিল্ডিং (পিইবি) এবং প্রিফ্যাব হাউজিং সময়মতো বাস্তবায়নের জন্য আমাদের অভিজ্ঞতা এবং সংস্থান রয়েছে।",
