    "We have the experience and resources to execute complex projects on time with international standards of quality, safety, and reliability. The company always gears up to excel stakeholders' expectations with its modern technology and sophisticated, experienced professional workforce.": "আন্তর্জাতিক মানের গুণমান, নিরাপত্তা এবং নির্ভরযোগ্যতার সাথে জটিল প্রকল্পগুলো সময়মতো বাস্তবায়নের জন্য আমাদের অভিজ্ঞতা এবং সংস্থান রয়েছে। আধুনিক প্রযুক্তি এবং পরিশীলিত, অভিজ্ঞ পেশাদার কর্মীবাহিনীর সাথে স্টেকহোল্ডারদের প্রত্যাশাকে ছাড়িয়ে যাওয়ার জন্য কোম্পানি সর্বদা প্রস্তুত।",
    "is a Bangladesh-based Real Estate and Housing Company. The Company undertakes projects on the basis of Engineering-Procurement-Construction & Commissioning (EPC&C), with the experience and resources to execute complex projects on time with international standards of quality, safety, and reliability.": "একটি বাংলাদেশ ভিত্তিক রিয়েল এস্টেট এবং হাউজিং কোম্পানি। কোম্পানিটি ইঞ্জিনিয়ারিং-প্রকিউরমেন্ট-কনস্ট্রাকশন অ্যান্ড কমিশনিং (EPC&C) ভিত্তিতে প্রকল্প গ্রহণ করে, আন্তর্জাতিক মানের গুণমান, নিরাপত্তা এবং নির্ভরযোগ্যতার সাথে জটিল প্রকল্পগুলো সময়মতো বাস্তবায়নের জন্য অভিজ্ঞতা এবং সংস্থান রয়েছে।",
