  for (const [key, val] of Object.entries(rawTranslations)) {
    translations[key] = val;
    translations[key.toLowerCase()] = val;
    translations[key.toUpperCase()] = val;
  }

  // Sort keys by length descending to match longest full sentences first
  const sortedKeys = Object.keys(translations).sort((a, b) => b.length - a.length);

  const urlParams = new URLSearchParams(window.location.search);
  let currentLang = urlParams.get('lang') || localStorage.getItem('bongshai_lang') || 'en';

  function applyLanguage(lang) {
    currentLang = lang;
    localStorage.setItem('bongshai_lang', lang);
    document.documentElement.setAttribute('lang', lang);

    const toggleBtn = document.getElementById('banglaLangToggle');
    if (toggleBtn) {
      toggleBtn.innerHTML = lang === 'bn' 
        ? '<span class="lang-inactive" style="font-family:sans-serif;">EN</span><span class="lang-active">বাংলা</span>' 
        : '<span class="lang-active" style="font-family:sans-serif;">EN</span><span class="lang-inactive">বাংলা</span>';
    }

    if (lang === 'bn') {
      translateDOM(document.body);
    } else {
      window.location.reload();
    }
  }

  const digitMap = {
    '0': '০', '1': '১', '2': '২', '3': '৩', '4': '৪', 
    '5': '৫', '6': '৬', '7': '৭', '8': '৮', '9': '৯'
  };

  function toBanglaDigits(str) {
    return str.replace(/[0-9]/g, match => digitMap[match]);
  }

  function translateText(text) {
    if (!text) return text;
    let normalized = text.replace(/\s+/g, ' ').trim();
    if (!normalized) return text;

    let result = text;
    let translated = false;

    // 1. Exact full text match
    if (translations[normalized]) {
      result = text.replace(text.trim(), translations[normalized]);
      translated = true;
    } 
    // 2. Case-insensitive exact full match
    else {
      const lower = normalized.toLowerCase();
      if (translations[lower]) {
        result = text.replace(text.trim(), translations[lower]);
        translated = true;
      }
    }

    // Always convert digits in the result if we are translating to Bangla
    // even if it was not in the dictionary (e.g. phone numbers, years, sizes)
    if (currentLang === 'bn') {
      const finalResult = toBanglaDigits(result);
      if (finalResult !== text) {
        return finalResult;
      }
    }

    // If node already contains Bangla text, do NOT perform partial substring replacement
    if (/[\u0980-\u09FF]/.test(text)) {
      return text;
    }

    return result;
  }

  function translateDOM(element) {
    if (!element) return;
    
    // 1. Text Nodes
    const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT, null, false);
    let node;
    const nodesToReplace = [];

    while (node = walker.nextNode()) {
      if (node.parentElement && ['SCRIPT', 'STYLE', 'CODE'].includes(node.parentElement.tagName)) {
        continue;
      }
      const originalText = node.nodeValue;
      if (!originalText || !originalText.trim()) continue;

      const translated = translateText(originalText);
      if (translated !== originalText) {
        nodesToReplace.push({ node, translated });
      }
    }

    nodesToReplace.forEach(item => {
      item.node.nodeValue = item.translated;
    });

    // 2. Attributes: placeholder, title, alt, value
    const attributeMap = ['placeholder', 'title', 'alt'];
    attributeMap.forEach(attr => {
      document.querySelectorAll(`[${attr}]`).forEach(el => {
        const val = el.getAttribute(attr);
        if (val && val.trim()) {
          const norm = val.replace(/\s+/g, ' ').trim();
          let translatedVal = val;
          if (translations[norm]) {
            translatedVal = translations[norm];
          } else if (translations[norm.toLowerCase()]) {
            translatedVal = translations[norm.toLowerCase()];
          }
          if (currentLang === 'bn') {
             translatedVal = toBanglaDigits(translatedVal);
          }
          if (translatedVal !== val) {
            el.setAttribute(attr, translatedVal);
          }
        }
      });
    });

    // 3. Input Values (Buttons)
    document.querySelectorAll('input[type="submit"], input[type="button"], input[type="reset"]').forEach(el => {
      const val = el.getAttribute('value');
      if (val && val.trim()) {
        const norm = val.replace(/\s+/g, ' ').trim();
        let translatedVal = val;
        if (translations[norm]) {
          translatedVal = translations[norm];
        } else if (translations[norm.toLowerCase()]) {
          translatedVal = translations[norm.toLowerCase()];
        }
        if (currentLang === 'bn') {
           translatedVal = toBanglaDigits(translatedVal);
        }
        if (translatedVal !== val) {
          el.setAttribute('value', translatedVal);
        }
      }
    });

    // 4. Meta Tags (SEO)
    const metaNames = ['description', 'geo.placename', 'og:title', 'og:description'];
    metaNames.forEach(name => {
      document.querySelectorAll(`meta[name="${name}"], meta[property="${name}"]`).forEach(el => {
        const val = el.getAttribute('content');
        if (val && val.trim()) {
          const norm = val.replace(/\s+/g, ' ').trim();
          let translatedVal = val;
          if (translations[norm]) {
            translatedVal = translations[norm];
          } else if (translations[norm.toLowerCase()]) {
            translatedVal = translations[norm.toLowerCase()];
          }
          if (translatedVal !== val) {
            el.setAttribute('content', translatedVal);
          }
        }
      });
    });

    // 5. Schema JSON-LD (SEO)
    document.querySelectorAll('script[type="application/ld+json"]').forEach(script => {
      try {
        let json = JSON.parse(script.textContent);
        let translated = false;
        function traverse(obj) {
          for (let key in obj) {
            if (typeof obj[key] === 'string') {
              const val = obj[key];
              const norm = val.replace(/\s+/g, ' ').trim();
              if (translations[norm]) {
                obj[key] = translations[norm];
                translated = true;
              } else if (translations[norm.toLowerCase()]) {
                obj[key] = translations[norm.toLowerCase()];
                translated = true;
              }
            } else if (typeof obj[key] === 'object' && obj[key] !== null) {
              traverse(obj[key]);
            }
          }
        }
        traverse(json);
        if (translated) {
          script.textContent = JSON.stringify(json, null, 2);
        }
      } catch (e) {}
    });
  }

  function injectLanguageToggle() {
    if (document.getElementById('banglaLangToggle')) return;

    const navInner = document.querySelector('.nav-cta') || 
                     document.querySelector('.navbar-inner') || 
                     document.querySelector('.nav-container') || 
                     document.querySelector('.navbar') || 
                     document.querySelector('#mainNav') || 
                     document.querySelector('header') || 
                     document.querySelector('.site-header') || 
                     document.body;
    if (!navInner) return;

    const btn = document.createElement('button');
    btn.id = 'banglaLangToggle';
    btn.type = 'button';
    btn.className = 'lang-toggle-btn';
    btn.setAttribute('aria-label', 'Toggle Language between English and Bangla');
    /* Custom styles injected via <style> tag */

    btn.innerHTML = currentLang === 'bn' 
      ? '<span class="lang-inactive" style="font-family:sans-serif;">EN</span><span class="lang-active">বাংলা</span>' 
      : '<span class="lang-active" style="font-family:sans-serif;">EN</span><span class="lang-inactive">বাংলা</span>';
      
    // Inject modern styles
    if (!document.getElementById('modernLangBtnStyles')) {
      const style = document.createElement('style');
      style.id = 'modernLangBtnStyles';
      style.textContent = `
        #banglaLangToggle {
          display: inline-flex;
          align-items: center;
          justify-content: center;
          padding: 4px 6px;
          margin-left: 12px;
          background: linear-gradient(135deg, rgba(255,255,255,0.9), rgba(255,255,255,0.6));
          backdrop-filter: blur(10px);
          -webkit-backdrop-filter: blur(10px);
          border: 1px solid rgba(217, 119, 6, 0.2);
          border-radius: 50px;
          font-size: 0.85rem;
          font-weight: 600;
          cursor: pointer;
          box-shadow: 0 4px 15px rgba(0,0,0,0.06), inset 0 1px 0 rgba(255,255,255,0.8);
          transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
          user-select: none;
          z-index: 9999;
          position: relative;
          gap: 4px;
        }
        #banglaLangToggle:hover {
          transform: translateY(-2px);
          box-shadow: 0 6px 20px rgba(217, 119, 6, 0.25), inset 0 1px 0 rgba(255,255,255,1);
          border-color: rgba(217, 119, 6, 0.5);
        }
        #banglaLangToggle:active {
          transform: translateY(1px);
          box-shadow: 0 2px 8px rgba(217, 119, 6, 0.15);
        }
        .lang-active {
          color: #ffffff;
          background: linear-gradient(135deg, #f59e0b, #d97706);
          padding: 4px 10px;
          border-radius: 20px;
          box-shadow: 0 2px 6px rgba(217, 119, 6, 0.4);
          transition: all 0.3s ease;
        }
        .lang-inactive {
          color: #777;
          padding: 4px 8px;
          transition: color 0.3s ease;
        }
        #banglaLangToggle:hover .lang-inactive {
          color: #333;
        }
      `;
      document.head.appendChild(style);
    }

    btn.addEventListener('click', function() {
      const nextLang = currentLang === 'en' ? 'bn' : 'en';
      const url = new URL(window.location.href);
      if (nextLang === 'bn') {
        url.searchParams.set('lang', 'bn');
      } else {
        url.searchParams.delete('lang');
      }
      window.history.pushState({}, '', url);
      applyLanguage(nextLang);
    });

    const quoteBtn = navInner.querySelector('.btn-primary, .nav-btn, .quote-btn');
    if (quoteBtn && quoteBtn.parentNode) {
      quoteBtn.parentNode.insertBefore(btn, quoteBtn);
    } else {
      navInner.appendChild(btn);
    }

    if (currentLang === 'bn') {
      applyLanguage('bn');
    }

    if (window.MutationObserver) {
      const observer = new MutationObserver(function(mutations) {
        if (currentLang === 'bn') {
          mutations.forEach(function(mutation) {
            mutation.addedNodes.forEach(function(node) {
              if (node.nodeType === 1) {
                translateDOM(node);
              }
            });
          });
        }
      });
      observer.observe(document.body, { childList: true, subtree: true });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', injectLanguageToggle);
  } else {
    injectLanguageToggle();
  }



